      "ਇਸ ਵਿੱਚ ਮੈਨੂੰ ਮੇਰੇ ਜਾਗਣ ਵਾਲੇ ਸੁਪਨਿਆਂ ਦਾ ਪਤਾ ਅਤੇ ਤੇਰੇ ਨਾਮ ਦੀ ਹਰ ਧੜਕਣ ਲੱਭ ਜਾਵੇਗੀ।"
