      "ਇਸੇ ਤਰ੍ਹਾਂ ਸੱਚੇ ਰਿਸ਼ਤੇ ਵੀ ਵਿਸ਼ਵਾਸ ਦੀ ਮਿੱਟੀ ਵਿੱਚ ਹੌਲੀ-ਹੌਲੀ ਖਿੜਦੇ ਹਨ।"
