      "କେବଳ ତୁମର ଆଖିର ସାମାନ୍ୟ ଥକ୍କା ଦ୍ୱାରା ତୁମର ଅବସ୍ଥା ଜାଣିବାର ପ୍ରତିଜ୍ଞା ଅଛି |"
