      "11 ଫେବୃଆରୀ ର ଏହି ପ୍ରକୃତ ପ୍ରତିଜ୍ଞା କ one ଣସି ଗୋଟିଏ season ତୁ ଉପରେ ନିର୍ଭରଶୀଳ ନୁହେଁ |"
