      "କ word ଣସି ଶବ୍ଦ ନ କହି, ମୋର ହୃଦୟର ପ୍ରତ୍ୟେକ ଭାର ତୁମ ବାହୁରେ ବିଚ୍ଛିନ୍ନ ହେଉ |"
